mapper.select:
SELECT CABA.SOURCE_KEY as project_id, CABA.ABS_BANK_ACCOUNT_ID, CABA.SOURCE_KEY, CABA.SOURCE_TYPE, CABA.ACCOUNT_SOURCE_TYPE, CABA.ABS_COMPANY_ID, CABA.ABS_COMPANY_NAME, CABA.BANK_ACCOUNT_TYPE, CABA.BANK_ACCOUNT_ID, CABA.BANK_ACCOUNT_NUM, CABA.BANK_ACCOUNT_NAME, CABA.BANK_BRANCH_NAME, CABA.DESCRIPTION, (select c.REF_V05 from csh_bank_account c where c.BANK_ACCOUNT_ID = CABA.BANK_ACCOUNT_ID) as BANK_ACCOUNT_ID_N, ( SELECT SC.MEANING FROM SC WHERE SC.CODE_VALUE = CABA.BANK_ACCOUNT_TYPE AND SC.CODE = 'ABS.ACCOUNT_TYPE' ) BANK_ACCOUNT_TYPE_DESC, ( SELECT meaning value_name FROM sys_code_value_b_v v WHERE v.CODE = 'LON_CON_ACCOUNT_SOURCE' AND v.code_value = CABA.ACCOUNT_SOURCE_TYPE) ACCOUNT_SOURCE_TYPE_N, ( SELECT meaning value_name FROM sys_code_value_b_v v WHERE v.CODE = 'ABS.ACCOUNT_TYPE' AND v.code_value = CABA.BANK_ACCOUNT_TYPE) BANK_ACCOUNT_TYPE_N
FROM CT_ABS_BANK_ACCOUNT CABA WHERE 1=1
AND CABA.SOURCE_KEY = #{sourceKey}
AND CABA.SOURCE_TYPE = #{sourceType}
AND CABA.ACCOUNT_SOURCE_TYPE = #{accountSourceType}
AND CABA.BANK_ACCOUNT_TYPE = #{bankAccountType}
AND CABA.BANK_ACCOUNT_NUM LIKE CONCAT('%',CONCAT(#{bankAccountNum},'%'))
AND CABA.BANK_ACCOUNT_NAME LIKE CONCAT('%',CONCAT(#{bankAccountName},'%'))
AND CABA.BANK_BRANCH_NAME LIKE CONCAT('%',CONCAT(#{bankBranchName},'%'))

SELECT DISTINCT CABA.ABS_COMPANY_ID, CABA.ABS_COMPANY_NAME FROM CT_ABS_BANK_ACCOUNT CABA WHERE 1=1
AND CABA.SOURCE_KEY = #{sourceKey}
AND CABA.SOURCE_TYPE = #{sourceType} queryOranization
AND CABA.ACCOUNT_SOURCE_TYPE = #{accountSourceType}
